import zlib from 'zlib';

/**
 * Gzip-compressed, byte-for-byte identical binaries of `public/models/keystroke.onnx`
 * and `public/models/mouse.onnx`. Because this file is statically imported by `onnxEngine.ts`,
 * Next.js / Vercel Serverless ALWAYS bundles it into the `/api/telemetry` lambda.
 */
const KEYSTROKE_ONNX_GZIP_B64 = '';
const MOUSE_ONNX_GZIP_B64 = '';

let cachedKeystrokeBuf: Uint8Array | null = null;
let cachedMouseBuf: Uint8Array | null = null;

export function getEmbeddedOnnxBuffer(filename: string): Uint8Array | null {
  if (filename === 'keystroke.onnx') {
    if (!cachedKeystrokeBuf) {
      const gunzipped = zlib.gunzipSync(Buffer.from(KEYSTROKE_ONNX_GZIP_B64, 'base64'));
      cachedKeystrokeBuf = new Uint8Array(gunzipped);
    }
    return cachedKeystrokeBuf;
  }
  if (filename === 'mouse.onnx') {
    if (!cachedMouseBuf) {
      const gunzipped = zlib.gunzipSync(Buffer.from(MOUSE_ONNX_GZIP_B64, 'base64'));
      cachedMouseBuf = new Uint8Array(gunzipped);
    }
    return cachedMouseBuf;
  }
  return null;
}
